28	/** Deterministic gentle wave around a base value — a placeholder trend that
29	 *  always looks alive even before RRD history is available. */
30	function seedWave(base: number, seed: number): number[] {
31	  const out: number[] = [];
32	  for (let i = 0; i < 24; i++) {
33	    const n = Math.sin((i + seed) * 0.7) * 0.12 + Math.sin((i + seed) * 1.9) * 0.05;
34	    out.push(Math.max(0, base * (1 + n)));
35	  }
36	  return out;
37	}
