import dns from "node:dns/promises";

/**
 * Custom-domain DNS verification for game servers.
 *
 * Customers can point their own domain (e.g. play.mydomain.com) at their game
 * server by creating an A record and an SRV record on their own DNS provider.
 * This module checks whether those records resolve correctly.
 *
 * We never create any DNS records ourselves — the customer does it on their
 * provider (Cloudflare, GoDaddy, Namecheap, etc.).
 */

export type DnsVerifyResult = {
  aOk: boolean;
  srvOk: boolean;
  /** The actual A-record value we found (if any) */
  aValue?: string;
  /** The SRV target we found */
  srvTarget?: string;
  /** The SRV port we found */
  srvPort?: number;
  /** Human-readable error detail (for unexpected failures) */
  aError?: string;
  srvError?: string;
};

/**
 * Verify that a customer's domain has the correct DNS records for connecting
 * to their game server.
 *
 * @param domain     - The customer's domain, e.g. "play.mydomain.com"
 * @param expectedIp - The IP address the A record should point to
 * @param expectedPort - The port the SRV record should advertise
 */
export async function verifyCustomDomainDns(
  domain: string,
  expectedIp: string,
  expectedPort: number,
): Promise<DnsVerifyResult> {
  const result: DnsVerifyResult = { aOk: false, srvOk: false };

  // --- Check A record ---
  try {
    const addresses = await dns.resolve4(domain);
    if (addresses.length > 0) {
      result.aValue = addresses[0];
      result.aOk = addresses.includes(expectedIp);
    }
  } catch (err: unknown) {
    const code = (err as NodeJS.ErrnoException).code;
    if (code === "ENOTFOUND" || code === "ENODATA") {
      result.aError = "No A record found for this domain.";
    } else {
      result.aError = `DNS lookup failed: ${code ?? "unknown error"}`;
    }
  }

  // --- Check SRV record ---
  const srvName = `_minecraft._tcp.${domain}`;
  try {
    const records = await dns.resolveSrv(srvName);
    if (records.length > 0) {
      const rec = records[0];
      result.srvTarget = rec.name;
      result.srvPort = rec.port;
      result.srvOk = rec.port === expectedPort;
    }
  } catch (err: unknown) {
    const code = (err as NodeJS.ErrnoException).code;
    if (code === "ENOTFOUND" || code === "ENODATA") {
      result.srvError = "No SRV record found.";
    } else {
      result.srvError = `SRV lookup failed: ${code ?? "unknown error"}`;
    }
  }

  return result;
}

