// ---------------------------------------------------------------------------
// Custom domain
// ---------------------------------------------------------------------------

/**
 * Valid hostname: letters, digits, hyphens, dots. No protocol, no path, no IP,
 * at least 4 chars (shortest: a.co). Max 253 chars per RFC 1035.
 */
const HOSTNAME_RE = /^(?!.*\.\.)(?!-)[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*\.[a-zA-Z]{2,}$/;
const IP_RE = /^\d{1,3}(\.\d{1,3}){3}$/;

function cleanDomain(raw: string): string {
  let d = raw.trim().toLowerCase();
  // Strip protocol prefix if someone pastes a URL
  d = d.replace(/^https?:\/\//i, "");
  // Strip trailing slash / path
  d = d.replace(/\/.*$/, "");
  return d;
}

function validateDomain(raw: string): { ok: true; domain: string } | { ok: false; error: string } {
  const domain = cleanDomain(raw);
  if (domain.length < 4) return { ok: false, error: "Domain is too short." };
  if (domain.length > 253) return { ok: false, error: "Domain is too long." };
  if (IP_RE.test(domain)) return { ok: false, error: "Enter a domain name, not an IP address." };
  if (!HOSTNAME_RE.test(domain)) return { ok: false, error: "Invalid domain format. Example: play.mydomain.com" };
  return { ok: true, domain };
}

/** Resolve the effective public IP and game port for a server. */
async function serverConnectInfo(serverId: string): Promise<{ ip: string; port: number } | null> {
  const s = await db.server.findUnique({
    where: { id: serverId },
    select: {
      dedicatedIp: { select: { address: true } },
      portForwards: { orderBy: { publicPort: "asc" } },
    },
  });
  if (!s) return null;

  const publicIp = process.env.PUBLIC_IP ?? "";

  if (s.dedicatedIp) {
    // Dedicated IP uses the default Minecraft port (25565)
    const pf = s.portForwards[0];
    return { ip: s.dedicatedIp.address, port: pf?.guestPort ?? 25565 };
  }

  if (s.portForwards.length > 0) {
    return { ip: publicIp, port: s.portForwards[0].publicPort };
  }

  return publicIp ? { ip: publicIp, port: 25565 } : null;
}

export type SetCustomDomainResult =
  | { ok: true; domain: string | null }
  | { ok: false; error: string };

/**
 * Set or clear the custom domain for a game server. Setting a new domain
 * resets verification — the customer must re-verify after changing it.
 */
export async function setCustomDomain(
  serverId: string,
  domain: string | null,
): Promise<SetCustomDomainResult> {
  try {
    const { user } = await ownedServer(serverId);
    const rl = throttle(user.id, "customDomain", 10);
    if (rl) return { ok: false, error: rl };

    if (domain === null || domain.trim() === "") {
      // Clear the custom domain
      await db.server.update({
        where: { id: serverId },
        data: { customDomain: null, customDomainVerified: false },
      });
      revalidatePath(`/dashboard/servers/${serverId}`);
      return { ok: true, domain: null };
    }

    const v = validateDomain(domain);
    if (!v.ok) return { ok: false, error: v.error };

    // Check if another server already uses this domain
    const existing = await db.server.findFirst({
      where: { customDomain: v.domain, id: { not: serverId } },
      select: { id: true },
    });
    if (existing) return { ok: false, error: "This domain is already in use on another server." };

    await db.server.update({
      where: { id: serverId },
      data: { customDomain: v.domain, customDomainVerified: false },
    });
    revalidatePath(`/dashboard/servers/${serverId}`);
    return { ok: true, domain: v.domain };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export type VerifyCustomDomainResult =
  | { ok: true; verified: boolean; dns: DnsVerifyResult; expectedIp: string; expectedPort: number }
  | { ok: false; error: string };

/**
 * Verify that the customer's DNS records are correctly configured for their
 * custom domain. Updates customDomainVerified if both A and SRV pass.
 */
export async function verifyCustomDomain(
  serverId: string,
): Promise<VerifyCustomDomainResult> {
  try {
    const { user } = await ownedServer(serverId);
    const rl = throttle(user.id, "customDomainVerify", 6);
    if (rl) return { ok: false, error: rl };

    const server = await db.server.findUnique({
      where: { id: serverId },
      select: { customDomain: true },
    });
    if (!server?.customDomain) {
      return { ok: false, error: "No custom domain set on this server." };
    }

    const info = await serverConnectInfo(serverId);
    if (!info) {
      return { ok: false, error: "Could not determine the server's public IP and port." };
    }

    const dns = await verifyCustomDomainDns(server.customDomain, info.ip, info.port);
    const verified = dns.aOk && dns.srvOk;

    await db.server.update({
      where: { id: serverId },
      data: { customDomainVerified: verified },
    });

    revalidatePath(`/dashboard/servers/${serverId}`);
    return { ok: true, verified, dns, expectedIp: info.ip, expectedPort: info.port };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

