"use client";

import { useState, useTransition } from "react";
import { setCustomDomain, verifyCustomDomain } from "@/lib/actions-game-control";
import type { DnsVerifyResult } from "@/lib/custom-domain-dns";

/* ------------------------------------------------------------------ */
/*  Copy helper (inline — avoids pulling in another client component) */
/* ------------------------------------------------------------------ */

function CopyCell({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);
  return (
    <button
      type="button"
      className="btn-ghost px-1.5 py-0.5 text-[10px]"
      onClick={() => {
        void navigator.clipboard.writeText(text).then(() => {
          setCopied(true);
          setTimeout(() => setCopied(false), 1400);
        });
      }}
    >
      {copied ? "Copied" : "Copy"}
    </button>
  );
}

/* ------------------------------------------------------------------ */
/*  Props                                                             */
/* ------------------------------------------------------------------ */

type Props = {
  serverId: string;
  /** Effective public IP players connect to */
  serverIp: string;
  /** Effective public port for the game */
  serverPort: number;
  /** Current custom domain (null = none set) */
  currentDomain: string | null;
  /** Whether the current domain is DNS-verified */
  verified: boolean;
};

/* ------------------------------------------------------------------ */
/*  Component                                                         */
/* ------------------------------------------------------------------ */

export function GameCustomDomain({
  serverId,
  serverIp,
  serverPort,
  currentDomain,
  verified: initialVerified,
}: Props) {
  const [domain, setDomain] = useState(currentDomain ?? "");
  const [savedDomain, setSavedDomain] = useState(currentDomain);
  const [verified, setVerified] = useState(initialVerified);
  const [dnsResult, setDnsResult] = useState<DnsVerifyResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [pending, startTransition] = useTransition();

  /* ----- Save / update domain ----- */
  function handleSave() {
    setError(null);
    setDnsResult(null);
    startTransition(async () => {
      const r = await setCustomDomain(serverId, domain.trim() || null);
      if (!r.ok) {
        setError(r.error);
        return;
      }
      setSavedDomain(r.domain);
      setVerified(false);
      if (!r.domain) setDomain("");
    });
  }

  /* ----- Remove domain ----- */
  function handleRemove() {
    setError(null);
    setDnsResult(null);
    startTransition(async () => {
      const r = await setCustomDomain(serverId, null);
      if (!r.ok) {
        setError(r.error);
        return;
      }
      setSavedDomain(null);
      setVerified(false);
      setDomain("");
    });
  }

  /* ----- Verify DNS ----- */
  function handleVerify() {
    setError(null);
    startTransition(async () => {
      const r = await verifyCustomDomain(serverId);
      if (!r.ok) {
        setError(r.error);
        return;
      }
      setDnsResult(r.dns);
      setVerified(r.verified);
    });
  }

  const hasDomain = !!savedDomain;
  const domainChanged = domain.trim().toLowerCase() !== (savedDomain ?? "");

  return (
    <div className="card space-y-5">
      <div className="flex items-center justify-between gap-2">
        <h3 className="font-semibold">Custom domain</h3>
        {hasDomain && (
          <span
            className={`rounded-full border px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide ${
              verified
                ? "border-emerald-500/25 bg-emerald-500/[0.08] text-emerald-300"
                : "border-amber-500/25 bg-amber-500/[0.08] text-amber-300"
            }`}
          >
            {verified ? "Verified" : "Pending verification"}
          </span>
        )}
      </div>

      <p className="text-sm text-slate-400">
        Point your own domain at this server so players can connect with your brand.{" "}
        <span className="text-slate-500">This is completely free.</span>
      </p>

      {/* ---- Domain input ---- */}
      <div className="flex flex-wrap items-end gap-2">
        <div className="min-w-0 flex-1">
          <label htmlFor="custom-domain" className="mb-1 block text-xs text-slate-400">
            Domain
          </label>
          <input
            id="custom-domain"
            type="text"
            placeholder="play.mydomain.com"
            value={domain}
            onChange={(e) => setDomain(e.target.value)}
            className="w-full rounded-lg border border-white/10 bg-navy-950/70 px-3 py-2 font-mono text-sm text-white placeholder:text-slate-600 focus:border-brand-400/50 focus:outline-none"
          />
        </div>
        <button
          type="button"
          className="btn-primary"
          disabled={pending || !domain.trim() || !domainChanged}
          onClick={handleSave}
        >
          {hasDomain ? "Update" : "Set domain"}
        </button>
        {hasDomain && (
          <button
            type="button"
            className="btn-danger"
            disabled={pending}
            onClick={handleRemove}
          >
            Remove
          </button>
        )}
      </div>

      {error && (
        <p className="text-xs text-red-400" role="alert">
          {error}
        </p>
      )}

      {/* ---- DNS instructions (shown once a domain is saved) ---- */}
      {hasDomain && (
        <>
          <div className="divider" />
          <div className="space-y-3">
            <h4 className="text-sm font-semibold text-slate-200">DNS records to create</h4>
            <p className="text-xs text-slate-400">
              Add these records at your domain provider (Cloudflare, GoDaddy, Namecheap, etc.).
              DNS changes can take up to 48 hours to propagate, but usually work within minutes.
            </p>

            {/* ---- Records table ---- */}
            <div className="overflow-x-auto rounded-lg border border-white/[0.08] bg-black/20">
              <table className="w-full text-left text-xs">
                <thead>
                  <tr className="border-b border-white/[0.06] text-[10px] uppercase tracking-wider text-slate-500">
                    <th className="px-3 py-2">Type</th>
                    <th className="px-3 py-2">Name / Host</th>
                    <th className="px-3 py-2">Value / Target</th>
                    <th className="px-3 py-2">Details</th>
                    <th className="px-3 py-2" />
                  </tr>
                </thead>
                <tbody className="font-mono text-slate-200">
                  <tr className="border-b border-white/[0.04]">
                    <td className="whitespace-nowrap px-3 py-2 font-semibold text-brand-300">A</td>
                    <td className="px-3 py-2">{savedDomain}</td>
                    <td className="px-3 py-2">{serverIp}</td>
                    <td className="px-3 py-2 font-sans text-slate-500">TTL: Auto</td>
                    <td className="px-3 py-2">
                      <CopyCell text={serverIp} />
                    </td>
                  </tr>
                  <tr>
                    <td className="whitespace-nowrap px-3 py-2 font-semibold text-accent-cyan">SRV</td>
                    <td className="px-3 py-2">_minecraft._tcp.{savedDomain}</td>
                    <td className="px-3 py-2">{savedDomain}</td>
                    <td className="whitespace-nowrap px-3 py-2 font-sans text-slate-400">
                      Priority: 0 &middot; Weight: 5 &middot; Port: {serverPort}
                    </td>
                    <td className="px-3 py-2">
                      <CopyCell text={`0 5 ${serverPort} ${savedDomain}`} />
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>

            {/* ---- Provider tips ---- */}
            <details className="group rounded-lg border border-white/[0.06] bg-navy-950/40">
              <summary className="cursor-pointer px-3 py-2 text-xs font-medium text-slate-300 group-open:border-b group-open:border-white/[0.06]">
                Provider-specific tips
              </summary>
              <div className="space-y-3 px-3 py-3 text-xs text-slate-400">
                <div>
                  <span className="font-semibold text-slate-300">Cloudflare</span>
                  <p className="mt-0.5">
                    Make sure the A record proxy is <strong className="text-amber-300">OFF</strong>{" "}
                    (DNS only / grey cloud icon). Cloudflare&apos;s proxy does not support game traffic.
                    For the SRV record, set <em>Service</em> to <code className="text-slate-300">_minecraft</code>,{" "}
                    <em>Protocol</em> to <code className="text-slate-300">_tcp</code>,{" "}
                    <em>Name</em> to <code className="text-slate-300">{savedDomain}</code>,{" "}
                    and <em>Target</em> to <code className="text-slate-300">{savedDomain}</code>.
                  </p>
                </div>
                <div>
                  <span className="font-semibold text-slate-300">GoDaddy / Namecheap</span>
                  <p className="mt-0.5">
                    Some providers want the SRV record split into separate fields.
                    Use <em>Service</em>: <code className="text-slate-300">_minecraft</code>,{" "}
                    <em>Protocol</em>: <code className="text-slate-300">_tcp</code>,{" "}
                    <em>Priority</em>: <code className="text-slate-300">0</code>,{" "}
                    <em>Weight</em>: <code className="text-slate-300">5</code>,{" "}
                    <em>Port</em>: <code className="text-slate-300">{serverPort}</code>,{" "}
                    <em>Target</em>: <code className="text-slate-300">{savedDomain}</code>.
                  </p>
                </div>
                <div>
                  <span className="font-semibold text-slate-300">Other providers</span>
                  <p className="mt-0.5">
                    If your provider asks for the SRV record as a single value, enter:{" "}
                    <code className="text-slate-300">0 5 {serverPort} {savedDomain}.</code>{" "}
                    (note the trailing dot after the domain).
                  </p>
                </div>
              </div>
            </details>
          </div>

          {/* ---- Verify ---- */}
          <div className="divider" />
          <div className="flex flex-wrap items-center gap-3">
            <button
              type="button"
              className="btn-primary"
              disabled={pending}
              onClick={handleVerify}
            >
              {pending ? "Checking..." : "Verify DNS"}
            </button>
            {verified && (
              <span className="text-xs text-emerald-400">
                DNS is correctly configured. Players can connect via{" "}
                <span className="font-mono font-semibold">{savedDomain}</span>.
              </span>
            )}
          </div>

          {/* ---- Verification results ---- */}
          {dnsResult && (
            <div className="space-y-2 rounded-lg border border-white/[0.08] bg-black/20 px-4 py-3">
              <DnsCheck
                label="A record"
                ok={dnsResult.aOk}
                detail={
                  dnsResult.aOk
                    ? `Points to ${dnsResult.aValue}`
                    : dnsResult.aValue
                      ? `Points to ${dnsResult.aValue} (expected ${serverIp})`
                      : dnsResult.aError ?? "Not found"
                }
              />
              <DnsCheck
                label="SRV record"
                ok={dnsResult.srvOk}
                detail={
                  dnsResult.srvOk
                    ? `Port ${dnsResult.srvPort} → ${dnsResult.srvTarget}`
                    : dnsResult.srvPort !== undefined
                      ? `Port ${dnsResult.srvPort} (expected ${serverPort})`
                      : dnsResult.srvError ?? "Not found"
                }
              />
              {!dnsResult.aOk && !dnsResult.srvOk && (
                <p className="mt-1 text-[11px] text-slate-500">
                  DNS changes can take a few minutes to propagate. Double-check your records and try again.
                </p>
              )}
            </div>
          )}
        </>
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  DNS check row                                                     */
/* ------------------------------------------------------------------ */

function DnsCheck({ label, ok, detail }: { label: string; ok: boolean; detail: string }) {
  return (
    <div className="flex items-start gap-2 text-xs">
      <span className={`mt-0.5 flex h-4 w-4 shrink-0 items-center justify-center rounded-full ${ok ? "bg-emerald-500/20 text-emerald-400" : "bg-red-500/20 text-red-400"}`}>
        {ok ? (
          <svg width="10" height="10" viewBox="0 0 10 10" fill="none"><path d="M2 5.5L4 7.5L8 3" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/></svg>
        ) : (
          <svg width="10" height="10" viewBox="0 0 10 10" fill="none"><path d="M3 3L7 7M7 3L3 7" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"/></svg>
        )}
      </span>
      <div>
        <span className={`font-semibold ${ok ? "text-emerald-300" : "text-red-300"}`}>{label}</span>
        <span className="ml-2 text-slate-400">{detail}</span>
      </div>
    </div>
  );
}

